import{_ as e,o as a,c as l,a3 as i}from"./chunks/framework.CDCjIvJ8.js";const f=JSON.parse('{"title":"Threat model","description":"","frontmatter":{},"headers":[],"relativePath":"security/threat-model.md","filePath":"security/threat-model.md","lastUpdated":1789296458000}'),r={name:"security/threat-model.md"};function d(n,t,s,o,c,h){return a(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="threat-model" tabindex="-1">Threat model <a class="header-anchor" href="#threat-model" aria-label="Permalink to &quot;Threat model&quot;">​</a></h1><h2 id="assets" tabindex="-1">Assets <a class="header-anchor" href="#assets" aria-label="Permalink to &quot;Assets&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Asset</th><th style="text-align:left;">Why it matters</th></tr></thead><tbody><tr><td style="text-align:left;">Student coursework</td><td style="text-align:left;">Academic work; unpublished and personal</td></tr><tr><td style="text-align:left;">Marks and evaluations</td><td style="text-align:left;">Academic record; tampering is academic misconduct</td></tr><tr><td style="text-align:left;">Student PII</td><td style="text-align:left;">Names, email addresses, institutional affiliation</td></tr><tr><td style="text-align:left;">Service credentials</td><td style="text-align:left;">Supabase service-role key, Groq, Resend, Qdrant, Neo4j</td></tr><tr><td style="text-align:left;">Inference budget</td><td style="text-align:left;">Directly convertible to money by an attacker</td></tr><tr><td style="text-align:left;">Reference corpus</td><td style="text-align:left;">Curated precedent, the platform&#39;s substantive value</td></tr></tbody></table><h2 id="adversaries" tabindex="-1">Adversaries <a class="header-anchor" href="#adversaries" aria-label="Permalink to &quot;Adversaries&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Adversary</th><th style="text-align:left;">Capability</th><th style="text-align:left;">Wants</th></tr></thead><tbody><tr><td style="text-align:left;">Curious student</td><td style="text-align:left;">Valid account</td><td style="text-align:left;">Other students&#39; marks, the answer keys</td></tr><tr><td style="text-align:left;">Malicious student</td><td style="text-align:left;">Valid account</td><td style="text-align:left;">A higher mark, or to damage a peer&#39;s</td></tr><tr><td style="text-align:left;">Compromised instructor</td><td style="text-align:left;">Valid elevated account</td><td style="text-align:left;">Alter marks, exfiltrate a cohort</td></tr><tr><td style="text-align:left;">External attacker</td><td style="text-align:left;">No account</td><td style="text-align:left;">Any of the above; or free inference</td></tr><tr><td style="text-align:left;">Automated scanner</td><td style="text-align:left;">No account</td><td style="text-align:left;">Known vulnerabilities, exposed secrets</td></tr></tbody></table><p>The curious student is the most likely and the easiest to underestimate. They have a legitimate account, the software is used daily, and the boundaries are guessable — incrementing an id in a URL is not an advanced technique.</p><h2 id="threats-and-mitigations" tabindex="-1">Threats and mitigations <a class="header-anchor" href="#threats-and-mitigations" aria-label="Permalink to &quot;Threats and mitigations&quot;">​</a></h2><h3 id="privilege-escalation" tabindex="-1">Privilege escalation <a class="header-anchor" href="#privilege-escalation" aria-label="Permalink to &quot;Privilege escalation&quot;">​</a></h3><p><strong>Was exploitable.</strong> The sign-up form offered a role dropdown.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Vector</th><th style="text-align:left;">Mitigation</th></tr></thead><tbody><tr><td style="text-align:left;"><code>role</code> in the registration body</td><td style="text-align:left;">Removed; <code>extra=&quot;forbid&quot;</code> rejects it loudly</td></tr><tr><td style="text-align:left;"><code>user_metadata.role</code> at provisioning</td><td style="text-align:left;">Only <code>app_metadata</code> is trusted; <code>ADMIN</code> never implicit</td></tr><tr><td style="text-align:left;">Open faculty sign-up</td><td style="text-align:left;">Gated by a hashed, use-limited institution code</td></tr><tr><td style="text-align:left;">Role edited in <code>localStorage</code></td><td style="text-align:left;">Role read from the database on every request</td></tr></tbody></table><h3 id="horizontal-access-peer-data" tabindex="-1">Horizontal access (peer data) <a class="header-anchor" href="#horizontal-access-peer-data" aria-label="Permalink to &quot;Horizontal access (peer data)&quot;">​</a></h3><p><strong>Was exploitable, five ways.</strong> See the <a href="/DraftForge-2/security/model">security model</a>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Vector</th><th style="text-align:left;">Mitigation</th></tr></thead><tbody><tr><td style="text-align:left;">Guessing an evaluation id</td><td style="text-align:left;">Ownership resolved server-side; 404 on failure</td></tr><tr><td style="text-align:left;">Submitting another student&#39;s draft</td><td style="text-align:left;">Draft and version ownership both verified</td></tr><tr><td style="text-align:left;">Completing another student&#39;s roadmap item</td><td style="text-align:left;">Join through <code>roadmaps</code> enforced</td></tr><tr><td style="text-align:left;">Cross-instructor grade override</td><td style="text-align:left;">Assignment ownership verified</td></tr><tr><td style="text-align:left;">Enumerating ids via 403 vs 404</td><td style="text-align:left;">Uniform 404</td></tr></tbody></table><h3 id="credential-attacks" tabindex="-1">Credential attacks <a class="header-anchor" href="#credential-attacks" aria-label="Permalink to &quot;Credential attacks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Vector</th><th style="text-align:left;">Mitigation</th></tr></thead><tbody><tr><td style="text-align:left;">Password guessing</td><td style="text-align:left;">5/min, 30/hr per IP; uniform failure message</td></tr><tr><td style="text-align:left;">Account enumeration</td><td style="text-align:left;">Identical response for unknown account and wrong password</td></tr><tr><td style="text-align:left;">Invitation token guessing</td><td style="text-align:left;">256-bit tokens; only hashes stored; rate limited</td></tr><tr><td style="text-align:left;">Token replay after logout</td><td style="text-align:left;">Refresh revoked server-side; rotation with reuse detection</td></tr><tr><td style="text-align:left;">Algorithm confusion</td><td style="text-align:left;">Permitted algorithm derived from the key, not the header</td></tr></tbody></table><h3 id="resource-abuse" tabindex="-1">Resource abuse <a class="header-anchor" href="#resource-abuse" aria-label="Permalink to &quot;Resource abuse&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Vector</th><th style="text-align:left;">Mitigation</th></tr></thead><tbody><tr><td style="text-align:left;">Unbounded inference spend</td><td style="text-align:left;">Per-user request limits <strong>and</strong> a daily token budget</td></tr><tr><td style="text-align:left;">Upload flooding</td><td style="text-align:left;">40/hr, 15 MB cap enforced while streaming</td></tr><tr><td style="text-align:left;">Decompression bombs</td><td style="text-align:left;">Ratio and uncompressed-size ceilings on DOCX; page cap on PDF</td></tr><tr><td style="text-align:left;">Mail-reputation damage</td><td style="text-align:left;">200 invitations/hr; 200 per batch</td></tr><tr><td style="text-align:left;">Unauthenticated compute</td><td style="text-align:left;"><code>/documents/classify</code> now requires auth</td></tr></tbody></table><h3 id="data-exfiltration" tabindex="-1">Data exfiltration <a class="header-anchor" href="#data-exfiltration" aria-label="Permalink to &quot;Data exfiltration&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Vector</th><th style="text-align:left;">Mitigation</th></tr></thead><tbody><tr><td style="text-align:left;">Cross-origin credentialed reads</td><td style="text-align:left;">Exact-origin allowlist; the <code>*.onrender.com</code> regex is gone</td></tr><tr><td style="text-align:left;">Secret in the frontend bundle</td><td style="text-align:left;">CI greps build output; only <code>VITE_API_URL</code> is exposed</td></tr><tr><td style="text-align:left;">Secrets in logs or traces</td><td style="text-align:left;">Sink-level redaction; collector strips auth headers</td></tr><tr><td style="text-align:left;">Secrets in the repository</td><td style="text-align:left;">gitleaks over full history, with project-specific detectors</td></tr><tr><td style="text-align:left;">Answer keys via the API</td><td style="text-align:left;">Column-level grants withhold them</td></tr></tbody></table><h3 id="tampering" tabindex="-1">Tampering <a class="header-anchor" href="#tampering" aria-label="Permalink to &quot;Tampering&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Vector</th><th style="text-align:left;">Mitigation</th></tr></thead><tbody><tr><td style="text-align:left;">Editing a mark</td><td style="text-align:left;">Overrides restricted to the owning instructor, and audited</td></tr><tr><td style="text-align:left;">Erasing the evidence</td><td style="text-align:left;"><code>audit_log</code> has no <code>UPDATE</code>/<code>DELETE</code> grant</td></tr><tr><td style="text-align:left;">Rewriting a marked draft</td><td style="text-align:left;"><code>draft_versions</code> is append-only</td></tr><tr><td style="text-align:left;">Altering history</td><td style="text-align:left;">Marks reference an immutable version</td></tr></tbody></table><h2 id="accepted-risks" tabindex="-1">Accepted risks <a class="header-anchor" href="#accepted-risks" aria-label="Permalink to &quot;Accepted risks&quot;">​</a></h2><p>Stated rather than omitted:</p><p><strong>Service-role key in the application.</strong> Compromising the backend compromises all data. Mitigated by the key existing only in the deployment environment, and by RLS covering every other access path. Migrating repositories to request- scoped clients would reduce this.</p><p><strong>Tokens in <code>localStorage</code>.</strong> An XSS exposes them. Mitigated by a strict CSP and React&#39;s escaping; httpOnly cookies are the real fix.</p><p><strong>Prompt injection via draft content.</strong> A student can put instructions in a draft the tutor reads. The realistic impact is coaxing the tutor into writing their clause — a pedagogical failure, not a breach, since the tutor has no privileged access and cannot alter a mark.</p><p><strong>A compromised instructor account.</strong> Nothing prevents an instructor with valid credentials from exfiltrating their own cohort. The audit log makes it attributable after the fact; MFA would reduce the likelihood.</p><p><strong>No MFA.</strong> Supabase supports it; it is not yet enforced. For instructor accounts, which can alter academic records, this is the most valuable single addition remaining.</p><h2 id="not-in-scope" tabindex="-1">Not in scope <a class="header-anchor" href="#not-in-scope" aria-label="Permalink to &quot;Not in scope&quot;">​</a></h2><ul><li>Physical security of managed providers</li><li>Denial of service beyond edge and application rate limiting</li><li>Nation-state adversaries</li><li>Supply-chain compromise of pinned dependencies (monitored, not prevented)</li></ul>',30)])])}const y=e(r,[["render",d]]);export{f as __pageData,y as default};
